package com.fifotech.task.service;
import com.fifotech.task.domain.User;import com.fifotech.task.dto.ApiDtos.*;import com.fifotech.task.exception.ApiException;import com.fifotech.task.repository.UserRepository;import com.fifotech.task.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}public LoginResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).filter(User::isActive).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return new LoginResponse(jwt.generate(u),u.getRole(),u.getFullName(),u.getEmail(),u.getId());}}
